import {starField,bindStars} from './pc-interactions.js';
import {createFilters,emptyFilters,selectedDates} from './discovery-filters.js';
export function createDiscovery(ctx){
const {state,agents,$,$$,esc,money,icon,btn,field,textarea,section,pageTitle,navigate,render,save,toast,openModal,closeModal,validate}=ctx;
const blank=emptyFilters;
const filters=createFilters(ctx,filteredAgents);
const knownSites=['NOL','YES24','멜론티켓','티켓링크'];
const avatar=(a,size='')=>`<span class="avatar ${a.color||'blue'} ${size}">${a.image?`<img src="${esc(a.image)}" alt="${esc(a.name)} 프로필">`:esc(a.initial||a.name?.[0]||'나')}<span class="avatar-spark">✦</span></span>`;
const badges=a=>`<span class="badges"><span class="badge verified">${icon('shield',12)}본인인증</span>${a.verified>1?`<span class="badge verified">${icon('check',12)}계좌인증</span>`:''}</span>`;
function filteredAgents(f=state.filters){
  const q=state.query.trim().toLowerCase();
  return agents.filter(a=>{
    const searchable=[a.name,a.intro,a.category,...a.sites,...(a.category==='콘서트'?['태연 콘서트','데이식스 콘서트']:a.category==='뮤지컬'?['뮤지컬 프리미어']:[])].join(' ').toLowerCase();
    const dates=a.availability||a.dates.map(d=>`2026-09-${String(d).padStart(2,'0')}`);
    return(!q||searchable.includes(q))&&a.fee>=Number(f.min||0)&&(!f.max||a.fee<=Number(f.max))&&a.rating>=Number(f.rating||0)&&a.success>=Number(f.success||0)&&(!selectedDates(f).length||selectedDates(f).some(d=>dates.includes(d)))&&(!f.sites?.length||f.sites.some(s=>a.sites.some(site=>site.trim().toLowerCase()===s.trim().toLowerCase())));
  }).sort((a,b)=>({low:a.fee-b.fee,high:b.fee-a.fee,rating:b.rating-a.rating,trades:b.trades-a.trades,success:b.success-a.success}[state.sort]||0));
}
function labels(){const f=state.filters;return[f.min||f.max?['price',`착수비 ${f.min?money(f.min):'0'}원 ~ ${f.max?money(f.max)+'원':'제한 없음'}`]:null,selectedDates(f).length?['date','예매 날짜 '+selectedDates(f).join(' · ')]:null,f.rating?['rating',`별점 ${f.rating} 이상`]:null,f.success?['success',`성공률 ${f.success}% 이상`]:null,f.sites?.length?['sites',f.sites.join(' · ')]:null].filter(Boolean);}
function card(a){return `<article class="agent-card pc-agent-card"><div class="agent-main">${avatar(a)}<div class="agent-copy"><div class="agent-title"><h3>${esc(a.name)}</h3>${badges(a)}</div><p>${esc(a.intro)}</p><div class="agent-stats"><span class="rating"><b>★</b><strong>${a.rating.toFixed(1)}</strong><span class="muted">(${a.reviews})</span></span><span class="stat-divider"></span><span>거래 <strong>${a.trades}회</strong></span><span class="stat-divider"></span><span>성공률 <strong>${a.success}%</strong></span></div></div><div class="pc-card-price"><span>착수비</span><strong>${money(a.fee)}<small>원부터</small></strong></div></div><div class="agent-bottom"><div class="site-tags">${a.sites.map(s=>`<span>${esc(s)}</span>`).join('')}<span class="response-time">${icon('clock',13)}평균 ${a.reply}분 응답</span></div><a class="pc-profile-link" href="#profile/${a.id}" data-nav="profile" data-id="${a.id}">프로필 보기 ${icon('arrow',16)}</a></div></article>`;}
function home(){const list=filteredAgents(),search=state.query||labels().length;
return `<section class="page-heading home-heading pc-hero"><div><h1>좋아하는 공연에,<br>한 걸음 <em>더 가까이.</em></h1><p>믿을 수 있는 티켓팅 도우미와 설레는 순간을 함께 준비해요.</p></div><div class="ticket-outline" aria-hidden="true"><img src="./home-ticket.svg" alt="" width="420" height="240"></div></section><div class="pc-search-row"><div class="search-container">${icon('search',23)}<input id="search" type="search" value="${esc(state.query)}" placeholder="공연명, 도우미 이름, 예매처를 검색해 보세요" aria-label="도우미 검색"><span class="search-hint">원하는 공연이 있나요?</span></div><div class="popular-shows"><span>인기 검색</span><button data-popular="태연 콘서트">태연 콘서트</button><button data-popular="뮤지컬 프리미어">뮤지컬 프리미어</button><button data-popular="데이식스 콘서트">데이식스 콘서트</button><small>예시</small></div></div><div class="pc-discovery-header"><div><span class="tiny-label">${search?'나에게 맞는 조건으로':'함께할 순간을 기다리는'}</span><h2>${search?'도우미 검색 결과':'이번 주, 주목할 도우미'}</h2><p>${search?`${list.length}명의 도우미를 찾았어요`:'꼼꼼한 안내와 좋은 후기로 눈길을 끄는 도우미예요.'}</p></div></div><div class="pc-filterbar"><div class="filter-chips">${[['price','가격'],['date','예매 날짜'],['rating','별점'],['success','성공률']].map(([key,label])=>`<div class="quick-filter-anchor"><button class="chip ${labels().some(([k])=>k===key)?'selected':''}" data-action="quick-filter" data-filter="${key}" aria-haspopup="dialog" aria-expanded="false">${label}${icon('down',13)}</button></div>`).join('')}</div><button class="filter-button" data-action="filters" aria-label="상세 필터">${icon('filter',18)} 필터</button></div><div class="pc-result-toolbar"><p>${search?'조건에 맞는 도우미':'지금 제일 핫한!'} <strong>${list.length}</strong> 명</p><label class="sort-label"><select id="sort" aria-label="도우미 정렬">${[['recommend','추천순'],['low','착수비 낮은순'],['high','착수비 높은순'],['rating','별점순'],['trades','거래 많은순'],['success','성공률순']].map(([v,t])=>`<option value="${v}" ${state.sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${labels().length?`<div class="pc-applied-filters">${labels().map(([k,label])=>`<button data-remove-filter="${k}" aria-label="${esc(label)} 필터 삭제">${esc(label)} ${icon('close',13)}</button>`).join('')}<button data-action="reset-filters">전체 초기화</button></div>`:''}<div class="home-layout pc-home-layout"><section><div id="agent-results" class="agent-list" aria-live="polite">${list.length?list.map(card).join(''):`<div class="empty">${icon('search',40)}<h3>조건에 맞는 도우미가 없어요</h3><p>검색어나 필터를 바꿔 다시 찾아보세요.</p>${btn('검색과 필터 초기화','reset-filters')}</div>`}</div><section class="home-alert-card" aria-labelledby="home-alert-title"><h3 id="home-alert-title">원하는 도우미가 없나요?</h3><p>조건에 맞는 도우미가 등록되면 알려드릴게요.</p><button class="btn secondary" data-action="helper-alert-settings">${state.helperAlert?.enabled?'알림 설정':'알림 받기'}</button></section></section><aside class="home-sidebar"><div class="guide-card"><div class="guide-icon">${icon('shield',26)}</div><span class="tiny-label">처음이어도 괜찮아요</span><h2>찾는 순간부터<br>결과를 확인할 때까지.</h2><ol class="guide-steps"><li><b>1</b><div><strong>나에게 맞는 도우미 찾기</strong><p>프로필과 거래 후기를 살펴보세요.</p></div></li><li><b>2</b><div><strong>원하는 조건으로 직접 요청</strong><p>공연, 좌석과 희망 수고비를 알려주세요.</p></div></li><li><b>3</b><div><strong>최종 조건 확인 후 안전결제</strong><p>도우미가 제안한 조건을 확인해요.</p></div></li></ol><button class="guide-link" data-nav="guide">이용 방법 자세히 보기 ${icon('arrow',17)}</button></div><div class="trust-note">${icon('shield',22)}<div><strong>확인할 수 있는 신뢰</strong><p>인증 정보와 플랫폼 거래 후기를<br>함께 확인하고 선택하세요.</p></div></div><div class="help-card"><span>궁금한 점이 있나요?</span><button data-nav="help">고객센터 ${icon('chevron',14)}</button></div></aside></div>`;
}
function favoriteButton(a,iconOnly=false){const liked=(state.favorites||[]).includes(a.id);return `<button class="favorite-chip ${iconOnly?'icon-only':''} ${liked?'selected':''}" data-action="favorite" data-id="${a.id}" aria-pressed="${liked}" aria-label="좋아요">${icon('heart',18)}${iconOnly?'':'좋아요'}</button>`;}
function favorites(){const list=agents.filter(a=>(state.favorites||[]).includes(a.id));return `${pageTitle('좋아요한 도우미','','my')}<div class="favorite-list">${list.length?list.map(a=>'<div class="favorite-entry">'+card(a)+favoriteButton(a)+'</div>').join(''):'<div class="empty"><h2>아직 좋아요한 도우미가 없어요</h2><p>프로필에서 좋아요를 눌러 모아 보세요.</p><button class="btn secondary" data-nav="home">도우미 찾기</button></div>'}</div>`;}
function profile(){const a=agents.find(a=>a.id===state.selected);if(!a)return `<div class="empty"><h1>도우미를 찾을 수 없어요</h1><p>목록에서 다시 선택해 주세요.</p><button class="btn primary" data-nav="home">도우미 찾기</button></div>`;
const reviews=state.profileTab==='reviews';return `${pageTitle('도우미 프로필','인증 정보와 거래 후기를 함께 살펴보세요.','home')}<div class="detail-layout"><div><section class="content-card profile-intro"><div class="profile-title">${avatar(a,'large')}<div><div class="agent-title"><h1>${esc(a.name)}</h1>${badges(a)}</div><p>${esc(a.intro)}</p><span class="rating"><b>★</b><strong>${reviewStats(a).average}</strong> · <button class="review-jump" data-action="profile-reviews">후기 ${reviewStats(a).count}개</button></span></div><div class="profile-tools">${favoriteButton(a,true)}<button class="icon-btn" data-action="profile-share" aria-label="프로필 링크 복사">${icon('share')}</button></div></div><div class="profile-stats">${[['성공률',a.success+'%'],['거래 횟수',a.trades+'회'],['평균 응답',a.reply+'분']].map(([k,v])=>`<div class="info-tile"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><p class="record-note">${icon('info',13)} 플랫폼 거래 기록 예시 · 소개와 경력은 도우미가 직접 작성해요.</p></section>${section('함께하기 전에 확인하세요',`<dl class="document-rows">${[['가능 예매처',a.sites.join(' · ')],['주로 맡는 분야',a.category],['활동 가능 시간',a.hours||'매일 10:00 ~ 22:00'],['최소 착수비',money(a.fee)+'원'],['수고비',money(a.successMin||10000)+' ~ '+money(a.successMax||50000)+'원 · 최종 조건에서 확정'],['활동 경력',a.career+' · 본인 작성']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="notice">${icon('shield',17)}연락처는 요청을 수락한 상대방에게만 공개돼요.</div>`)}<section class="content-card profile-feedback" id="profile-feedback"><div class="tabs" role="tablist" aria-label="프로필 정보"><button data-profile-tab="about" class="${!reviews?'active':''}" role="tab" aria-selected="${!reviews}">도우미 소개</button><button data-profile-tab="reviews" class="${reviews?'active':''}" role="tab" aria-selected="${reviews}">거래 후기 ${reviewStats(a).count}</button></div>${reviews?profileReviews(a):`<h3>공연을 기다리는 마음, 함께할게요.</h3><p class="prose">${esc(a.detail||'희망하는 공연과 좌석 조건을 꼼꼼히 확인하고, 충분히 이야기한 뒤 예매를 준비해요.\n\n진행 상황과 결과를 빠르게 알려드릴게요. 모든 예매는 예매처가 허용하는 방법으로 진행해요.').replaceAll('\n','<br>')}</p><p class="record-note">도우미가 직접 작성한 소개예요.</p>`}</section><button class="report-link" data-nav="help">도움이 필요하거나 신고할 내용이 있나요?</button></div><aside class="sticky-card"><div class="content-card action-card"><span>최소 착수비</span><div class="display-price">${money(a.fee)}<small>원부터</small></div><p>수고비는 성공 조건에 따라<br>도우미가 최종 조건으로 제안해요.</p>${state.mode==='user'?btn('이 도우미에게 요청하기','quote','primary full'):'<button class="btn secondary full" data-mode="user">이용자로 전환해 요청하기</button>'}<div class="action-assurance">${icon('shield',15)}요청은 무료예요</div></div><p class="aside-disclaimer">요청 → 도우미 수락 및 최종 조건 전달<br>→ 이용자 확인·확정 → 안전거래 결제</p></aside></div>`;}
// Deterministic demo reviews; the distribution and total share the same dataset.
let reviewObserver;
function reviewData(a){
 const lowCount=Math.round((5-a.rating)*a.reviews);
 const comments=['희망 조건을 꼼꼼히 확인하고 진행 과정을 바로 알려주셔서 편하게 기다렸어요.','공연장 좌석을 잘 알고 계셔서 도움이 됐어요. 다음에도 함께하고 싶어요.','안내가 친절하고 진행 상황도 빠르게 알려주셨어요.','요청한 내용을 잘 확인해 주셔서 안심하고 맡겼어요.'];
 const demo=Array.from({length:a.reviews},(_,i)=>({name:['김○정','이○은','박○서','최○아'][i%4],date:new Date(Date.UTC(2026,8,12-Math.floor(i/3))).toISOString().slice(0,10),rating:i>=a.reviews-lowCount?4:5,text:comments[i%comments.length]}));
 const written=(state.reviews||[]).filter(r=>r.agentId===a.id).map(r=>({...r,name:r.author||state.profile.name||'이용자',date:r.createdAt?.slice(0,10)||null,text:r.comment})).reverse();
 return [...written,...demo];
}
function reviewStats(a){const rows=reviewData(a);return {count:rows.length,average:rows.length?(rows.reduce((n,r)=>n+r.rating,0)/rows.length).toFixed(1):'0.0',counts:[5,4,3,2,1].map(n=>rows.filter(r=>r.rating===n).length)};}
function reviewItem(r){return `<article class="review-item"><div class="review-author"><strong>${esc(r.name)}</strong><span class="badge verified">${icon('check',12)}거래 인증</span></div><div class="review-rating-date"><span class="stars" aria-label="${r.rating}점">${'★'.repeat(r.rating)}<span class="empty-stars">${'☆'.repeat(5-r.rating)}</span></span><time ${r.date?'datetime="'+esc(r.date)+'"':''}>${r.date?esc(r.date.replaceAll('-','.')):'작성일 미기록'}</time></div><p>${esc(r.text)}</p></article>`;}
function profileReviews(a){const stats=reviewStats(a);return `<div class="review-summary"><div class="review-score"><strong>${stats.average}</strong><span class="stars">★★★★★</span><small>거래 후기 ${stats.count}개 · 예시 포함</small></div><div class="review-distribution" aria-label="별점 분포">${stats.counts.map((count,i)=>`<div class="review-bar-row"><span>${5-i}점</span><div class="review-bar-track" role="meter" aria-label="${5-i}점 후기" aria-valuemin="0" aria-valuemax="${stats.count}" aria-valuenow="${count}"><span style="width:${stats.count?count/stats.count*100:0}%"></span></div><small>${count}개</small></div>`).join('')}</div></div><div id="profile-review-list"></div><div id="review-sentinel" class="review-list-status" role="status"></div>`;}
function bindReviewList(){
 reviewObserver?.disconnect();
 const list=$('#profile-review-list'),sentinel=$('#review-sentinel');if(!list||!sentinel)return;
 const a=agents.find(a=>a.id===state.selected),rows=reviewData(a);let loaded=0;
 const append=()=>{list.insertAdjacentHTML('beforeend',rows.slice(loaded,loaded+20).map(reviewItem).join(''));loaded=Math.min(loaded+20,rows.length);sentinel.textContent=loaded<rows.length?'아래로 스크롤하면 후기가 이어져요.':'모든 후기를 확인했어요.';if(loaded>=rows.length)reviewObserver?.disconnect();};
 append();if(loaded<rows.length){reviewObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))append();},{rootMargin:'200px'});reviewObserver.observe(sentinel);}
}
function review(){const r=state.requests.find(r=>r.id===state.selected);if(!r||state.mode!=='user'||r.status!=='completed'||r.reviewed)return `${pageTitle('후기를 작성할 수 없어요','거래 완료 후 한 번만 작성할 수 있어요.','requests')}`;const d=state.drafts['review-'+r.id]||{};return `${pageTitle('후기 작성','함께한 경험을 다른 이용자에게 알려 주세요.','detail')}<div class="account-contained">${section(esc(r.show),`<form id="review-form">${starField(d.rating)}${textarea('comment','후기',d.comment||'')}<p class="notice">${icon('shield',17)}완료한 거래의 후기에는 거래 인증 배지가 표시돼요.</p><div class="account-form-footer"><button type="submit" class="btn primary">후기 등록하기</button></div></form>`)}</div>`;}
function bind(){filters.close();bindStars();bindReviewList();
 const rf=$('#review-form');if(rf){rf.oninput=()=>{state.drafts['review-'+state.selected]=Object.fromEntries(new FormData(rf));save();};rf.onsubmit=e=>{e.preventDefault();const r=state.requests.find(r=>r.id===state.selected);if(!state.loggedIn||state.mode!=='user'||!r||r.status!=='completed'||r.reviewed||!validate(rf))return;const rating=Number(rf.elements.rating.value);if(![1,2,3,4,5].includes(rating)){$('.star-field .field-error',rf).textContent='별점을 선택해 주세요.';$('[data-star="1"]',rf).focus();return;}state.reviews.push({agentId:r.agentId,requestId:r.id,rating,comment:rf.elements.comment.value.trim(),author:state.profile.name,createdAt:new Date().toISOString(),verified:true});r.reviewed=true;delete state.drafts['review-'+r.id];save();navigate('detail',r.id);toast('거래 후기를 남겼어요.');};}
 if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;state.query=e.target.value;save();render();$('#search').focus();try{$('#search').setSelectionRange(pos,pos);}catch{}};if($('#sort'))$('#sort').onchange=e=>{state.sort=e.target.value;save();render();};$$('[data-popular]').forEach(b=>b.onclick=()=>{state.query=b.dataset.popular;save();render();});$$('[data-remove-filter]').forEach(b=>b.onclick=()=>{const k=b.dataset.removeFilter;if(k==='price'){state.filters.min=0;state.filters.max=0;}else if(k==='date'){state.filters.dates=[];delete state.filters.date;}else state.filters[k]=blank()[k];save();render();});$$('[data-profile-tab]').forEach(b=>b.onclick=()=>{state.profileTab=b.dataset.profileTab;render();});}
function helperAlertSettings(){
 const current=state.helperAlert;
 openModal('도우미 알림 설정',`<form id="helper-alert-form"><p class="prose">현재 검색어와 필터 조건으로 새 도우미 알림을 설정해요.</p><label class="check-row" style="margin:24px 0"><input type="checkbox" name="enabled" ${current?.enabled?'checked':''}>조건에 맞는 도우미 알림 받기</label><p class="record-note">체험용 설정이며 실제 알림은 발송되지 않아요.</p><div class="modal-actions"><button type="submit" class="btn primary">저장하기</button></div></form>`,{onReady:root=>{
  root.querySelector('#helper-alert-form').onsubmit=e=>{e.preventDefault();const enabled=e.currentTarget.elements.enabled.checked;state.helperAlert={enabled,query:state.query,filters:structuredClone(state.filters)};save();closeModal();render();toast(enabled?'도우미 알림 설정을 저장했어요.':'도우미 알림을 껐어요.');};
 }});
}
function handle(a,el){if(a==='profile-reviews'){state.profileTab='reviews';render();requestAnimationFrame(()=>$('#profile-feedback')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));}else if(a==='favorite'){const id=Number(el.dataset.id);state.favorites??=[];state.favorites=state.favorites.includes(id)?state.favorites.filter(v=>v!==id):[...state.favorites,id];save();const y=window.scrollY;render();window.scrollTo({top:y,behavior:'instant'});}else if(a==='helper-alert-settings')helperAlertSettings();else if(a==='quick-filter')filters.quick(el.dataset.filter,el);else if(a==='filters')filters.detailed();else if(a==='reset-filters'){state.filters=blank();state.query='';save();render();}else if(a==='quote'){state.quoteEditId=null;navigate('quote',state.selected);}else if(a==='profile-share')navigator.clipboard?.writeText(location.href).then(()=>toast('프로필 링크를 복사했어요.')).catch(()=>toast('주소 표시줄의 링크를 복사해 주세요.'));else return false;return true;}
return{pages:{home,profile,review,favorites},bind,handle,filteredAgents};
}

